def project_card(p):
 slug,cat,title,desc,sub,css=p
 return f'''<article class="work-card" data-category="{cat.lower().replace(' & ','-')}"><button class="work-picture {css}" type="button" data-project="{slug}" aria-label="View details of {title}"><span class="mock-browser"><i></i><i></i><i></i></span><span class="mock-project-title">{title.split()[0]}<small>{title.split()[-1]}</small></span><span class="project-detail-label">VIEW CONCEPT ↗</span></button><div class="work-info"><div><span class="mini-label">{cat} · CONCEPT</span><h3>{title}</h3><p>{desc}</p></div><button class="icon-link" data-project="{slug}" aria-label="Open {title} case study">↗</button></div></article>'''

